/* @socom-skeleton body Clear__9CGameMenuFv */
void CGameMenu::Clear()
{
	/* 0x3835a0: tear the current menu down - planes, pop-up, the UI texture buffer's
	 * lists, font, libraries, the menu's anim set, controls and objects, commands */
	if (m_popupnode != NULL)
	{
		m_popupnode->SetActive(false);
		m_popupnode = NULL;
	}

	GetMenuStack()->CleanPopup();

	m_nodeTop.DeleteChild(m_pBackplaneNode);

	if (m_pBackplaneNode != NULL)
		delete m_pBackplaneNode;

	m_pBackplaneNode = NULL;
	m_nodeTop.DeleteChild(m_pForeplaneNode);
	g_pFaderNode = NULL;
	/* port: not written - InvalidateSkbsDisplay() (0x383700) */

	if (m_pForeplaneNode != NULL)
		delete m_pForeplaneNode;

	m_pForeplaneNode = NULL;
	m_pBackplaneNode = zdb::CNode::Create("CGameMenu backplane");
	m_pForeplaneNode = zdb::CNode::Create("CGameMenu foreplane");
	m_nodeTop.AddChild(m_pBackplaneNode);
	m_nodeTop.AddChild(m_pForeplaneNode);
	m_pForeplaneNode->SetPosition(0.0f, 0.0f, 16777210.0f);

	/* texture buffer 0 forgets its textures and chain */
	zdb::CGSTexBuffer* buffer = reinterpret_cast<zdb::CGSTexBuffer*>(zdb::CTexManager::m_texmanager[0]); /* port: see doAddBuffer */
	buffer->m_dyntex_list.m_tex_list.clear();
	buffer->m_dyntex_list.m_pal_list.clear();
	buffer->m_chainp = NULL;
	/* port: not written - the buffer's +0x1c vector is emptied too (0x383728) */

	_font.m_charlist.clear();
	_font.m_pTexHandle = NULL;
	_font.m_displaytop = 0;
	_font.m_displaybottom = 0;
	_font.XPadding = 0;
	_font.m_avgWidth = 0.0f;

	if (_pFontLib != NULL)
		zdb::CAssetMgr::ReleaseLibRef(_pFontLib);

	_pFontLib = NULL;

	for (int i = (int)_vecLibs.size() - 1; i >= 0; i--)
		zdb::CAssetMgr::ReleaseLibRef(_vecLibs[i]);

	_vecLibs.clear();

	if (g_hasAnims)
	{
		g_hasAnims = false;

		if (glocal_anims != NULL)
		{
			CZAnimSet* set = glocal_anims;
			set->Stop();
			set->Unload();
		}
	}

	while (!m_ScreenControls.empty())
	{
		C2D* item = m_ScreenControls.front();
		m_ScreenControls.pop_front();
		delete item;
	}

	while (!m_ScreenElements.empty())
	{
		C2D* item = m_ScreenElements.front();
		m_ScreenElements.pop_front();
		delete item;
	}

	/* the ELF frees the strings of the first 10 commands only */
	for (u32 i = 0; i < 10; i++)
	{
		if (m_commands[i].Animation != NULL)
			_free(m_commands[i].Animation, "zui.cpp", 0x2b4);

		m_commands[i].Animation = NULL;

		if (m_commands[i].Argument != NULL)
			_free(m_commands[i].Argument, "zui.cpp", 0x2b5);

		m_commands[i].Argument = NULL;
	}

	m_numCommands = 0;
	m_activeButton = 0;

	if (m_has_mpeg_background && m_movieRunning)
		CMPEG::End();

	m_movieRunning = false;
	/* 0x383a50: the MODELS instances are deleted (the vector keeps its storage) */
	for (u32 i = 0; i < _vecModelInstances.size(); i++)
		zdb::CNode::Delete(_vecModelInstances[i]);

	_vecModelInstances.clear();
	g_pTtySound = NULL;
	zUIScheduler.ClearFreeList(true);
	/* port: not written - theUIVarManager.CollectGarbage() (0x383ac0) */
	m_has_mpeg_background = false;
}

/* @socom-skeleton stub Draw2dOnly__9CGameMenuFv */
void CGameMenu::Draw2dOnly()
{
	/* 0x383550: the whole menu tree (m_nodeTop, at the menu's start) as UI, with the
	 * backplane as the pipe's node */
	thePipe.m_node = m_pBackplaneNode;
	thePipe.m_simpletrans = true;
	thePipe.RenderUiNode(&m_nodeTop);
	thePipe.m_simpletrans = false;
}

/* @socom-skeleton body DrawForeplane__9CGameMenuFv */
void CGameMenu::DrawForeplane()
{
	thePipe.m_node = m_pForeplaneNode;
	// Enable orthographic view for UI layer
	thePipe.m_simpletrans = true;
	thePipe.RenderUiNode(m_pForeplaneNode);
	// Disable orthographic view for UI layer
	thePipe.m_simpletrans = false;
}

/* @socom-skeleton stub HandlePad__9CGameMenuFPC4CPad */
void CGameMenu::HandlePad(const CPad *pad)
{
	/* 0x382f00: track the left stick (centred with hysteresis), then the first taker of
	 * the pad: a shown pop-up, the soft keyboard, the active control, the design's
	 * BUTTON anims; else DOWN/RIGHT (or the stick) move to the next control and UP/LEFT
	 * to the previous one */
	g_bCenterSinceEdge = IsStickNearCenter(g_bCenterSinceEdge ? 0.6f : 0.2f);
	g_fStickX = pad->m_LeftStickDilated[0];
	g_fStickY = pad->m_LeftStickDilated[1];

	if (m_popupnode != NULL && m_popupnode->m_active)
	{
		GetMenuStack()->GetPopUp()->HandlePad(pad, 0);
		return;
	}

	if (SkbHandleInput(*pad, this))
		return;

	if (m_ScreenControls.HandlePad(pad, m_activeButton))
		return;

	for (s32 i = 0; i < m_numCommands; i++)
	{
		ActionItem& item = m_commands[i];

		if (item.Type != ActionItem::ACTION_TYPE_BUTTON || item.State != pad->m_state[item.PadButton])
			continue;

		CZAnim* anim = ZAnim.GetAnim(item.Animation, NULL);

		if (anim == NULL)
			return;

		if (item.Argument != NULL)
			anim->ActivateArg(1, 8, item.Argument, 0);
		else
			anim->Activate(NULL);

		return;
	}

	u8 dir;

	if (pad->m_state[(u8)PAD_BUTTON::PAD_DOWN] == KEY_FALLING || pad->m_state[(u8)PAD_BUTTON::PAD_RIGHT] == KEY_FALLING)
	{
		MakeNextButtonActive();
		return;
	}

	dir = UiGetDirStickMoved();

	if (dir == 2 || dir == 4)
	{
		MakeNextButtonActive();
		return;
	}

	if (pad->m_state[(u8)PAD_BUTTON::PAD_UP] == KEY_FALLING || pad->m_state[(u8)PAD_BUTTON::PAD_LEFT] == KEY_FALLING)
	{
		MakePrevButtonActive();
		return;
	}

	dir = UiGetDirStickMoved();

	if (dir == 1 || dir == 3)
		MakePrevButtonActive();
}

/* @socom-skeleton body Init__9CGameMenuFPQ23zdb16CTextureRelocMgrP9CZAnimZAR */
bool CGameMenu::Init(zdb::CTextureRelocMgr* manager, CZAnimZAR* archive)
{
	/* 0x382d80: read this menu's design (GetReaderFileName in data/common/dialog) and
	 * build it, inside one relocation batch. */
	Clear();
	animfile = archive;
	zVid.pcrtcDo = false;
	m_Reloc = manager ? manager : &g_relocBatch;
	m_Reloc->StartBatchReloc();

	if (animfile != NULL)
	{
		char* name = GetReaderFileName();
		CGameDlgDesign design;
		bool loaded = false;

		if (CRdrFile* rdr = zrdr_read(name, "data/common/dialog", LoadDialogsFromReader))
		{
			design.LoadFromRdr(rdr);
			zrdr_free(rdr);
			loaded = true;
		}

#ifdef SOCOM_PORT
		SOCOM_PORT_TRACE("UI: design %s %s: %u libs (%s), font '%s', background '%s' (%s), %u controls, %u objects, %u animations, script '%s'",
			name, loaded ? "read" : "missing", (u32)design.m_libs.size(), design.m_libs.size() ? design.m_libs[0].c_str() : "",
			design.m_font.c_str(), design.m_background.c_str(), design.m_useMpeg ? "mpeg" : "image",
			(u32)design.m_controls.size(), (u32)design.m_objects.size(), (u32)design.m_animations.size(), design.m_script.c_str());
#endif

		if (loaded)
		{
			m_ReaderName = name;
			LoadFromDesign(design, animfile);
		}
	}

	m_Reloc->EndBatchReloc();
	return true;
}

/* @socom-skeleton body LoadFromDesign__9CGameMenuFRC14CGameDlgDesignP9CZAnimZAR */
void CGameMenu::LoadFromDesign(const CGameDlgDesign &design, CZAnimZAR *animfile)
{
	/* 0x382180 */
	Clear();
	UiSetCounterSpeedFactor(1.0f);
	UiSetTtySpeedFactor(1.0f);

	for (u32 i = 0; i < design.m_libs.size(); i++)
	{
		const char* name = design.m_libs[i].c_str();

		if (*name != '\0')
		{
			zdb::CAssetLib* lib = zdb::CAssetMgr::GetLoadedLibRef(name);
			lib->m_autoload = false;
			HookupLib(lib);
			_vecLibs.push_back(lib);
		}
	}

	const char* fontname = design.m_font.c_str();

	if (design.m_fontlib)
	{
		_pFontLib = zdb::CAssetMgr::GetLoadedLibRef("common/assetlib/font");
		_pFontLib->m_autoload = false;
	}
	else
	{
		_pFontLib = NULL;
	}

	_font.Load(FetchMissionFontsRdr(), fontname);
	m_Reloc->AddToBatch(_font.m_pTexHandle);

	const char* background = design.m_background.c_str();

	if (!design.m_useMpeg)
	{
		zdb::CTextureRelocMgr* reloc = m_Reloc;
		zdb::CTexHandle* handle = NULL;

		if (background != NULL)
		{
			handle = zdb::CAssetMgr::m_assets.GetTexHandle(background);

			if (handle == NULL || handle->m_texture == NULL)
				handle = NULL;
			else
				reloc->AddToBatch(handle);
		}

		if (handle != NULL && handle->m_texture != NULL)
		{
			_bmpBackground.C2DBitmap::Load(0.0f, 0.0f, 640.0f, 448.0f, handle);
			Add2dNode(&_bmpBackground, reloc, m_pBackplaneNode);
		}
	}

	/* 0x382408: the design's ANIMATIONS become the menu's event/button commands */
	for (u32 i = 0; i < design.m_animations.size(); i++)
	{
		m_commands[m_numCommands] = design.m_animations[i];
		g_hasAnims = true;
#ifdef SOCOM_PORT
		SOCOM_PORT_TRACE("UI: command %u: %s %u anim '%s' arg '%s'", (u32)m_numCommands,
			m_commands[m_numCommands].Type ? "event" : "button", (u32)m_commands[m_numCommands].Event,
			m_commands[m_numCommands].Animation ? m_commands[m_numCommands].Animation : "",
			m_commands[m_numCommands].Argument ? m_commands[m_numCommands].Argument : "");
#endif
		m_numCommands++;
	}

	g_pFaderNode = Add2dNode(&_bmpFade, m_Reloc, m_pForeplaneNode);
	g_pFaderNode->SetName("MENUFADER");
	_bmpFade.SetTrans(128.0f);

	/* Controls, then the other objects: each spec makes its display object, hung on a
	 * node under the named parent (else the backplane) at its design position. */
	for (u32 i = 0; i < design.m_controls.size(); i++)
	{
		const CDesignDlgObj& obj = design.m_controls[i];
		C2D* item = obj.m_spec->CreateDisplayObj(&_font, m_Reloc);
		zdb::CNode* parent = *obj.m_parent.c_str() ? m_nodeTop.FindChild(obj.m_parent.c_str(), true) : NULL;

		if (parent == NULL)
			parent = m_pBackplaneNode;

		zdb::CNode* node = Add2dNode(item, m_Reloc, parent);
		node->SetPosition((f32)obj.m_x, (f32)obj.m_y, 0.0f);
		node->SetName(obj.m_name.c_str());
		m_ScreenControls.push_back(item);
		/* port: not written - a spec with children (HasChildren/NumChildren/GetChild) adds
		 * each child the same way, appended to the control's own list. */
	}

	for (u32 i = 0; i < design.m_objects.size(); i++)
	{
		const CDesignDlgObj& obj = design.m_objects[i];
		C2D* item = obj.m_spec->CreateDisplayObj(&_font, m_Reloc);
		zdb::CNode* parent = *obj.m_parent.c_str() ? m_nodeTop.FindChild(obj.m_parent.c_str(), true) : NULL;

		if (parent == NULL)
			parent = m_pBackplaneNode;

		zdb::CNode* node = Add2dNode(item, m_Reloc, parent);
		node->SetPosition((f32)obj.m_x, (f32)obj.m_y, 0.0f);
		node->SetName(obj.m_name.c_str());
		m_ScreenElements.push_back(item);
	}

	PrepControls(m_Reloc);
	PrepModels(design);

	/* the fader moves to the end of the foreplane, in front of everything */
	m_pForeplaneNode->DeleteChild(g_pFaderNode);
	m_pForeplaneNode->AddChild(g_pFaderNode);
	PrepSkbsForDisplay(m_pForeplaneNode, m_Reloc, &_font);

	/* 0x382a00: the pop-up dialog takes the menu's font and relocator and hangs, hidden, on a
	 * "POPUP" node in the foreplane (Add2dNode inline) */
	CPopUpDialog* popup = GetMenuStack()->GetPopUp();
	popup->m_font = &_font;
	popup->Load(m_Reloc);
	m_popupnode = Add2dNode(popup, m_Reloc, m_pForeplaneNode);
	m_popupnode->SetName("POPUP");
	m_popupnode->SetActive(false);

	if (!g_hasAnims)
	{
		_bmpFade.SetTrans(0.0f);
	}
	else
	{
		/* the dialog's ZAnim script: its anim set from the UI ZAR, started on the menu's
		 * scheduler, then the ONSTART anims */
		const char* script = design.m_script.c_str();
		char path[520];

		if (animfile != NULL)
			ZAnim.LoadZAR(animfile, script);

		sprintf(path, "data/common/dialog/%s", script);
		ZAnim.Load(path, script);
		glocal_anims = ZAnim.GetAnimSet(script);

		if (glocal_anims != NULL)
		{
			glocal_anims->m_task_scheduler = &zUIScheduler;
			glocal_anims->Start();
		}

#ifdef SOCOM_PORT
		SOCOM_PORT_TRACE("UI: anim set %s %p: %d anims, %d commands", script, glocal_anims,
			glocal_anims ? glocal_anims->m_anim_count : 0, (int)m_numCommands);
#endif
		RunEventAnim(ActionItem::ONSTART, NULL);
	}

	if (!m_ScreenControls.empty())
	{
		C2D* first = m_ScreenControls.front();
		m_activeButton = 0;

		if (first == NULL || !first->CanHandleInput())
			MakeNextButtonActive();
		else
			first->SetActive();
	}

	if (design.m_useMpeg)
	{
		m_MPEGName = background ? background : "";
		m_has_mpeg_background = true;
		/* port: stub - no MPEG playback in the port: the ELF ends the FIFO, runs
		 * CMPEG::Run(background, true, false) and re-enables the FIFO (0x382c84); here the
		 * movie does not run, as when Run fails */
		m_movieRunning = false;
	}

	if (m_has_mpeg_background && !m_movieRunning)
		RunEventAnim(ActionItem::ONMPEGEND, NULL);

	g_pTtySound = CSnd::GetSoundByName(theGame.m_menuState.TtySoundString.c_str());
}

/* @socom-skeleton stub RunEventAnim__9CGameMenuFQ210ActionItem5EVENTPCc */
void CGameMenu::RunEventAnim(ActionItem::EVENT event, const char *argument)
{
	/* 0x382030: activate the design's anims for that event, from the menu's own set
	 * first; the given argument (else the design's) goes to the anim as a string */
	for (s32 i = 0; i < m_numCommands; i++)
	{
		ActionItem& item = m_commands[i];

		if (item.Type != ActionItem::ACTION_TYPE_EVENT || item.Event != event)
			continue;

		CZAnim* anim = glocal_anims ? glocal_anims->Anim(item.Animation) : NULL;

		if (anim == NULL)
			anim = ZAnim.GetAnim(item.Animation, NULL);

		if (anim == NULL)
			continue;

		if (argument != NULL)
			anim->ActivateArg(1, 8, argument, 0);
		else if (item.Argument != NULL)
			anim->ActivateArg(1, 8, item.Argument, 0);
		else
			anim->Activate(NULL);
	}
}

/* @socom-skeleton stub MakeNextButtonActive__9CGameMenuFv */
void CGameMenu::MakeNextButtonActive()
{
	/* 0x381d20: the active control goes NORMAL and the next one (wrapping) ACTIVE with
	 * the selection sound; one that takes no input is passed over while any control
	 * still takes input */
	if (m_ScreenControls.empty())
		return;

	auto it = m_ScreenControls.begin();
	std::advance(it, m_activeButton);
	(*it)->SetNormal();
	m_activeButton = (m_activeButton + 1) % (s32)m_ScreenControls.size();

	it = m_ScreenControls.begin();
	std::advance(it, m_activeButton);
	C2D* control = *it;

	if (control->CanHandleInput())
	{
		control->SetActive();
		PlaySelectionSound();
		return;
	}

	for (it = m_ScreenControls.begin(); it != m_ScreenControls.end(); ++it)
	{
		if ((*it)->CanHandleInput())
		{
			MakeNextButtonActive();
			return;
		}
	}
}

/* @socom-skeleton stub MakePrevButtonActive__9CGameMenuFv */
void CGameMenu::MakePrevButtonActive()
{
	/* 0x381a10: as MakeNextButtonActive, backwards */
	if (m_ScreenControls.empty())
		return;

	auto it = m_ScreenControls.begin();
	std::advance(it, m_activeButton);
	(*it)->SetNormal();
	m_activeButton--;

	if (m_activeButton < 0)
		m_activeButton = (s32)m_ScreenControls.size() - 1;

	it = m_ScreenControls.begin();
	std::advance(it, m_activeButton);
	C2D* control = *it;

	if (control->CanHandleInput())
	{
		control->SetActive();
		PlaySelectionSound();
		return;
	}

	for (it = m_ScreenControls.begin(); it != m_ScreenControls.end(); ++it)
	{
		if ((*it)->CanHandleInput())
		{
			MakePrevButtonActive();
			return;
		}
	}
}

/* @socom-skeleton stub MakeButtonActive__9CGameMenuFPCc */
void CGameMenu::MakeButtonActive(const char *name)
{
	/* 0x3817e0: the active control goes NORMAL; the named node's control goes ACTIVE (with
	 * the selection sound) and becomes the active index */
	if (m_ScreenControls.empty())
		return;

	auto it = m_ScreenControls.begin();
	std::advance(it, m_activeButton);
	(*it)->SetNormal();

	C2D* control = NULL; /* port: the ELF leaves its register unset when the node has no 2D visual */
	zdb::CNode* node = m_nodeTop.FindChild(name, true);

	if (node != NULL)
	{
		zdb::CVisual* visual = node->GetFirstVisual();
		C2DVisual* visual2d = visual ? visual->Get2DVisual() : NULL;

		if (visual2d != NULL)
			control = visual2d->m_2d;

		if (control != NULL)
		{
			control->SetActive();
			PlaySelectionSound();
		}
	}

	s32 index = 0;

	for (it = m_ScreenControls.begin(); it != m_ScreenControls.end(); ++it, ++index)
	{
		if (*it == control)
		{
			m_activeButton = index;
			return;
		}
	}
}

